  // console.log(filteredData);



  return (
    <div>
      <div>
        {filteredData.map((elm, i)=>
       <div key={i}>
         <img src={elm.images[0]} alt="photoOfProducts" />
         <img src={elm.images[1]} alt="photoOfProducts" />
         <img src={elm.images[2]} alt="photoOfProducts" />

       </div>

        )}
      </div>
      <div>

      <p>{id}</p>
      </div>
    </div>
  );
};

export default EachProduct;
